import json
from prepare import ROOT, MATERIAL, write
references=json.loads((MATERIAL/'references.json').read_text())
claims={
 'rag-document-granularity':[
  ('rag_sequence','RAG-Sequence keeps the same document throughout the answer.',[1,2],'RAG physical page 3, Section 2.1; both cited excerpts explicitly describe the same-document sequence.'),
  ('rag_token','RAG-Token can use a different document for each token.',[1,2],'RAG physical page 3, Section 2.1; both cited excerpts state per-token document choice.')],
 'retriever-training-hop':[
  ('retriever_bridge','The pretrained retriever initializing RAG is DPR.',[1,4],'Cited RAG page 5 explicitly says the retriever is initialized using DPR; cited pages 1-2 describe pretrained components and name Dense Passage Retriever. These jointly support the bridge, although the frozen literal page-3 anchor is not supplied.'),
  ('negative_gold','The best DPR model uses gold passages from the same mini-batch as negatives.',[2],'DPR page 3, Training: exact best-model sentence, with gold and in-batch definitions in the same supplied passage.'),
  ('negative_bm25','The best DPR model also uses one BM25 negative passage.',[2],'DPR page 3, Training: exact best-model sentence states one BM25 negative passage.')],
 'lecture-overfitting':[
  ('overfitting_definition','Overfitting means fitting noise or attending to irrelevant data.',[1],'Physical PDF page 35, printed Slide 69; exact definition in supplied source.'),
  ('overfitting_effect','Overfitting may reduce test-set performance.',[1],'Physical PDF page 35, printed Slide 69; exact effect in supplied source.')],
}
rows=[]
for ref in references['cases']:
 name=ref['case_id'];raw=json.loads((ROOT/(name+'-planned.json')).read_text());emitted=[]
 for fact,claim,ids,reason in claims.get(name,[]):
  emitted.append(dict(fact_id=fact,claim=claim,citation_ids=ids,faithful=True,citation_required=True,citation_supported=True,citation_covered=True,review=reason,sources=[s for s in raw['answer']['sources'] if s['source_id'] in ids]))
 correct={c['fact_id'] for c in emitted}
 points=[dict(fact_id=f,correct=f in correct,complete=f in correct,supplied_semantic_evidence=f in correct,reason='Supported by exact supplied context and original page.' if f in correct else 'No answer delivered: processing error.' if raw['status']=='error' else 'Incorrect full refusal after all four generated queries resolved a generic phrase as an absent filename.') for f in ref['fact_ids']]
 passed=name in {'rag-document-granularity','retriever-training-hop','lecture-overfitting','forecast-is-not-actual'}
 rows.append(dict(case_id=name,status=raw['status'],answerability=ref['answerability'],answer=raw.get('answer',{}).get('answer'),passed=passed,expected_points=points,claims=emitted,requested_gaps=ref['gap_ids'],relevant=raw['status']=='completed',history_matches=raw.get('history_matches',False),physical_page_review='Supplied regions match original physical pages; lecture printed slide labels are not PDF page indices.' if emitted else 'not_applicable: no emitted cited factual claims',assessment_review='Final supported points select the relevant exact passages.' if emitted else 'Assessor correctly marks actual FY26 Q1 revenue missing; claim-free local refusal.' if name=='forecast-is-not-actual' else 'No context after incorrect scope resolution; local all-missing assessment follows retrieval failure.' if name=='income-period-basis' else 'Raw assessor correctly identifies available bridge and absent recipe, but an invalid supplementary query aborts validation and the request. See failure-reproduction.json.'))
summary=dict(case_gate=dict(passed=4,total=6,required=6,accepted=False),correctness=dict(correct=7,expected=13),completeness=dict(complete=7,expected=13),semantic_final_evidence_coverage=dict(covered=7,expected=13),faithfulness=dict(supported=7,claims=7),citation_support=dict(supported=7,cited_claims=7),citation_coverage=dict(covered=7,citation_required_claims=7),relevance=dict(relevant=5,total=6,completed_only=dict(relevant=5,total=5)),abstention=dict(appropriate_full=dict(passed=1,total=1),incorrect_full_on_fully_answerable=dict(count=1,total=4),incorrect_partial_on_fully_answerable=dict(count=0,total=4),partial_case_gap_disclosure=dict(passed=0,total=2,unavailable_due_processing_error=2),partial_supported_bridge=dict(delivered=0,total=1,error_omission=1,incorrect_refusal=0),note='Transport error is not successful abstention. The two local refusals emit no factual claims and have no citation denominator.'))
write('review.json',dict(at=datetime.now(timezone.utc).isoformat(),reviewer='Codex (model)',human_review=False,method='Frozen original-page facts plus exact final supplied source snapshots; every expected point and all emitted substantive claims reviewed. Repeated wording in the same answer is one claim. Joint citations assessed together; valid IDs alone are not support.',summary=summary,cases=rows,limitations=['First-use project corpus, but public papers can be familiar to pretrained models. One sample each, no independent human review.','Factual-claim scores exclude errors and claim-free refusals; read them with 4/6 case gate and 7/13 point completion.','Literal-anchor coverage differs from semantic coverage because valid alternate RAG bridge passages were supplied.']))
