write('dependency-review.json',dict(reviewer='Codex (model)',eligible_chains=1,executed_dependent_chains=0,status='not_exercised',gate_passed=False,reason='Planner generated two independent queries and no dependencies; both execute in round 1. No binding or target-derived downstream round occurred.',answer_quality_passed=True,round_count=len(hop['hops']['rounds']),planned_dependencies=hop['trace']['plan']['dependencies'],bindings=hop['hops']['bindings'],executed_queries=[dict(round_index=r['round_index'],text=r['text'],requested_file_ids=r['requested_file_ids']) for r in hop['trace']['runs']],restricted_scope=json.loads((ROOT/'failure-reproduction.json').read_text())['restricted'],material_status='Development material from first result inspection onward; no tuning or answer replay performed in this run.'))
